const b=$input.first().json.body||{};
const L=['en','ar','hi','zh','ur','es'].includes(b.lang)?b.lang:'en';
const T={
  en: `Reminder: ${b.bill} (£${b.amount}) is due on ${b.dueDate}. Balance after payment: £${b.balanceAfter}.`,
  ar: `تذكير: ${b.bill} (£${b.amount}) مستحق في ${b.dueDate}. الرصيد بعد الدفع: £${b.balanceAfter}.`,
  hi: `याद दिलाना: ${b.bill} (£${b.amount}) की अंतिम तिथि ${b.dueDate} है। भुगतान के बाद बैलेंस: £${b.balanceAfter}।`,
  zh: `提醒：${b.bill}（£${b.amount}）将于${b.dueDate}到期。付款后余额：£${b.balanceAfter}。`,
  ur: `یاد دہانی: ${b.bill} (£${b.amount}) کی آخری تاریخ ${b.dueDate} ہے۔ ادائیگی کے بعد بیلنس: £${b.balanceAfter}۔`,
  es: `Recordatorio: ${b.bill} (£${b.amount}) vence el ${b.dueDate}. Saldo tras el pago: £${b.balanceAfter}.`
};
const D={"en": "Guidance, not regulated financial advice.", "ar": "إرشاد وليس نصيحة مالية منظمة.", "hi": "मार्गदर्शन, विनियमित वित्तीय सलाह नहीं।", "zh": "仅为指导，非受监管的财务建议。", "ur": "رہنمائی، منظم مالی مشورہ نہیں۔", "es": "Orientación, no asesoramiento financiero regulado."};
return [{json:{message:T[L]+' '+D[L],lang:L}}];
